{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01WE9AniU6TRy6nMTZVwTZfg","type":"tool_result","content":[{"type":"text","text":"{"commits":[{"hash":"a6f911cf3612608cac9649229396e0ebc92ae8ba","date":"2026-08-20T15:59:32-04:00","message":"(test) Add \"golden schemas\" for encounter payloads (#787)","refs":"","body":"Co-authored-by: Dennis Kigen <kigen.work@gmail.com>","authorName":"Ian","authorEmail":"52504170+ibacher@users.noreply.github.com"},{"hash":"12c24b6731b62e0993ae8ecbe666b13785f71f6e","date":"2026-06-12T12:11:44+03:00","message":"(fix) O3-5735: Only send default encounter datetimes for stopped visits","refs":"","body":"PR #756 made new encounters always submit an explicit encounterDatetime,\nfalling back to the client-clock session date. On browsers running ahead\nof server time this produces a future datetime that the backend rejects\nwith Encounter.datetimeShouldBeBeforeCurrent, breaking form submissions\nin active visits (caught by patient-chart's clock-skew e2e test).\n\nRestore the previous behavior for active visits and visit-less encounters:\nomit encounterDatetime so the backend defaults it to server time. Keep\nsending the visit-window-clamped session date for stopped visits, which\nis the retrospective data entry case O3-5735 fixed.\n","authorName":"denniskigen","authorEmail":"kigen.work@gmail.com"},{"hash":"b99cb4c27946bf936dce89d37baebe31720f8ef8","date":"2026-06-11T23:02:01+03:00","message":"(fix) O3-5735: Keep default encounter datetimes within the visit window during retrospective data entry (#756)","refs":"","body":"","authorName":"Dennis Kigen","authorEmail":"kigen.work@gmail.com"}],"totalCount":3}"}]}]},"parent_tool_use_id":null,"session_id":"e747080a-6a4d-4bdc-8efe-c5babb2c8c48","uuid":"37088041-29d8-47a9-814b-adbac665a565","timestamp":"2026-10-23T17:59:11.935Z","tool_use_result":[{"type":"text","text":"{"commits":[{"hash":"a6f911cf3612608cac9649229396e0ebc92ae8ba","date":"2026-08-20T15:59:32-04:00","message":"(test) Add \"golden schemas\" for encounter payloads (#787)","refs":"","body":"Co-authored-by: Dennis Kigen <kigen.work@gmail.com>","authorName":"Ian","authorEmail":"52504170+ibacher@users.noreply.github.com"},{"hash":"12c24b6731b62e0993ae8ecbe666b13785f71f6e","date":"2026-06-12T12:11:44+03:00","message":"(fix) O3-5735: Only send default encounter datetimes for stopped visits","refs":"","body":"PR #756 made new encounters always submit an explicit encounterDatetime,\nfalling back to the client-clock session date. On browsers running ahead\nof server time this produces a future datetime that the backend rejects\nwith Encounter.datetimeShouldBeBeforeCurrent, breaking form submissions\nin active visits (caught by patient-chart's clock-skew e2e test).\n\nRestore the previous behavior for active visits and visit-less encounters:\nomit encounterDatetime so the backend defaults it to server time. Keep\nsending the visit-window-clamped session date for stopped visits, which\nis the retrospective data entry case O3-5735 fixed.\n","authorName":"denniskigen","authorEmail":"kigen.work@gmail.com"},{"hash":"b99cb4c27946bf936dce89d37baebe31720f8ef8","date":"2026-06-11T23:02:01+03:00","message":"(fix) O3-5735: Keep default encounter datetimes within the visit window during retrospective data entry (#756)","refs":"","body":"","authorName":"Dennis Kigen","authorEmail":"kigen.work@gmail.com"}],"totalCount":3}"}],"tool_result_meta":[{"id":"toolu_01WE9AniU6TRy6nMTZVwTZfg","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
